window.SEARCH_INDEX=[{"id": "structure", "url": "structure.html", "title": "Script structure", "text": "script structure every script should start with a shebang and, for most scripts, \u201cstrict mode\u201d. keep logic inside functions and call main at the bottom. #!/usr/bin/env bash # my-script.sh \u2014 one-line description of what it does set -euo pipefail readonly script_dir=\"$(cd \"$(dirname \"${bash_source[0]}\")\" && pwd)\" usage() { echo \"usage: $(basename \"$0\") <arg>\"; } main() { [[ $# -ge 1 ]] || { usage; exit 1; } echo \"hello, $1\" } main \"$@\" line meaning #!/usr/bin/env bash find bash on path . more portable than #!/bin/bash , which on macos is the old bash 3.2. set -e exit right away when a command fails. set -u treat unset variables as an error. set -o pipefail a pipeline fails if any command in it fails, not just the last. main \"$@\" pass every argument through to main , unchanged. running a script chmod +x my-script.sh # make executable (once) ./my-script.sh arg1 # run it bash my-script.sh arg1 # run without exec permission source lib.sh # run in the current shell (also: . lib.sh)"}, {"id": "variables", "url": "variables.html", "title": "Variables & quoting", "text": "variables & quoting name=\"world\" # no spaces around = echo \"hello, $name\" # hello, world echo \"hello, ${name}!\" # braces mark where the name ends echo 'hello, $name' # single quotes: no expansion \u2192 hello, $name readonly pi=3.14 # constant export path=\"$home/bin:$path\" # make visible to child processes unset name # delete variable today=$(date +%f) # command substitution (prefer over backticks) files=$(ls | wc -l) always quote variables , as in \"$var\" . without quotes, bash splits the value on spaces and expands globs, so rm $file with file=\"my notes.txt\" tries to delete my and notes.txt . special variables variable meaning $0 script name $1 \u2026 $9, ${10} positional arguments $# number of arguments \"$@\" all arguments, each kept as a separate word (almost always what you want) \"$*\" all arguments joined into one string $? exit code of the last command $$ pid of the current shell $! pid of the last background job $_ last argument of the previous command $random random integer 0\u201332767 $lineno , $seconds current line number; seconds since the shell started"}, {"id": "expansion", "url": "expansion.html", "title": "Parameter expansion", "text": "parameter expansion built-in string manipulation, with no need for sed or cut . file=\"/home/user/photos/beach.tar.gz\" ${file##*/} # beach.tar.gz strip longest match from start (basename) ${file%/*} # /home/user/photos strip shortest match from end (dirname) ${file#*.} # tar.gz strip shortest match from start ${file##*.} # gz extension ${file%.*} # /home/user/photos/beach.tar ${file%%.*} # /home/user/photos/beach ${#file} # 31 length ${file:6:4} # user substring (offset:length) ${file: -6} # tar.gz last 6 chars (note the space) ${file/photos/pics} # replace first match ${file//o/0} # replace all matches ${file^^} # uppercase (bash 4+) ${file,,} # lowercase (bash 4+) defaults & required values syntax result ${var:-default} use default if var is unset or empty ${var:=default} same, and also assign it to var ${var:+other} use other only if var is set ${var:?message} exit with message if var is unset or empty port=\"${port:-8080}\" input=\"${1:?usage: $0 <input-file>}\" brace expansion echo {a,b,c}.txt # a.txt b.txt c.txt echo {1..5} # 1 2 3 4 5 echo {01..10..3} # 01 04 07 10 mkdir -p project/{src,tests,docs} cp config.yml{,.bak} # cp config.yml config.yml.bak"}, {"id": "arrays", "url": "arrays.html", "title": "Arrays", "text": "arrays indexed arrays fruits=(\"apple\" \"banana\" \"cherry\") fruits+=(\"date\") # append echo \"${fruits[0]}\" # apple echo \"${fruits[@]}\" # all elements echo \"${#fruits[@]}\" # length \u2192 4 echo \"${!fruits[@]}\" # indices \u2192 0 1 2 3 echo \"${fruits[@]:1:2}\" # slice \u2192 banana cherry unset 'fruits[1]' # remove element for f in \"${fruits[@]}\"; do echo \"$f\"; done files=(*.txt) # array from a glob mapfile -t lines < file.txt # array of lines (bash 4+) associative arrays (bash 4+) declare -a ports=([http]=80 [https]=443) ports[ssh]=22 echo \"${ports[https]}\" # 443 for key in \"${!ports[@]}\"; do echo \"$key \u2192 ${ports[$key]}\" done [[ -v ports[ftp] ]] || echo \"no ftp key\" macos ships bash 3.2, which has no associative arrays or mapfile . run brew install bash to get bash 5."}, {"id": "arithmetic", "url": "arithmetic.html", "title": "Arithmetic", "text": "arithmetic a=10; b=3 echo $(( a + b )) # 13 echo $(( a / b )) # 3 (integer division) echo $(( a % b )) # 1 echo $(( a ** 2 )) # 100 (( a++ )) # increment (( count += 5 )) (( a > b )) && echo \"a is bigger\" # floating point \u2014 bash only does integers; use bc or awk echo \"scale=2; 10 / 3\" | bc # 3.33 awk 'begin { printf \"%.2f\\n\", 10/3 }' # 3.33"}, {"id": "conditionals", "url": "conditionals.html", "title": "Conditionals & tests", "text": "conditionals & tests if [[ -f \"$file\" ]]; then echo \"file exists\" elif [[ -d \"$file\" ]]; then echo \"it's a directory\" else echo \"not found\" fi # one-liners [[ -z \"$name\" ]] && echo \"name is empty\" [[ -d \"$dir\" ]] || mkdir -p \"$dir\" # test a command's success directly if grep -q \"error\" log.txt; then echo \"found errors\"; fi if ! command -v jq >/dev/null; then echo \"jq not installed\"; fi use [[ \u2026 ]] instead of [ \u2026 ] in bash. it handles empty variables safely and supports && , || , =~ regex, and glob patterns. file tests test true if\u2026 -e path exists -f path is a regular file -d path is a directory -l path is a symlink -r / -w / -x path is readable / writable / executable -s path exists and isn't empty a -nt b / a -ot b a is newer / older than b string tests test true if\u2026 -z \"$s\" string is empty -n \"$s\" string is not empty \"$a\" == \"$b\" strings are equal ( != for not equal) \"$s\" == *.txt glob match (no quotes on the pattern) \"$s\" =~ ^[0-9]+$ regex match; groups go into ${bash_rematch[@]} numeric tests test meaning -eq -ne equal, not equal -lt -le less than, less or equal -gt -ge greater than, greater or equal (( a > b )) arithmetic form, often easier to read combining [[ -f \"$f\" && -r \"$f\" ]] [[ \"$env\" == \"prod\" || \"$env\" == \"staging\" ]] [[ ! -e \"$f\" ]]"}, {"id": "case", "url": "case.html", "title": "case statements", "text": "case statements case \"$1\" in start) echo \"starting\u2026\" ;; stop|halt) echo \"stopping\u2026\" ;; *.tar.gz|*.tgz) tar -xzf \"$1\" ;; [0-9]*) echo \"starts with a digit\" ;; -h|--help) usage ;; *) echo \"unknown: $1\" >&2 exit 1 ;; esac"}, {"id": "loops", "url": "loops.html", "title": "Loops", "text": "loops # over a list for name in alice bob carol; do echo \"hi $name\"; done # over files (glob \u2014 never parse `ls`) for f in *.jpg; do [[ -e \"$f\" ]] || continue # skip if no matches echo \"processing $f\" done # ranges for i in {1..10}; do echo \"$i\"; done for (( i = 0; i < 10; i += 2 )); do echo \"$i\"; done # while / until count=0 while (( count < 5 )); do (( count++ )); done until ping -c1 example.com &>/dev/null; do sleep 1; done # infinite loop with break while true; do read -rp \"continue? [y/n] \" ans [[ \"$ans\" == n ]] && break done break exits the loop and continue skips to the next iteration. both take a number to act on outer loops, as in break 2 ."}, {"id": "functions", "url": "functions.html", "title": "Functions", "text": "functions greet() { local name=\"${1:-stranger}\" # `local` keeps variables scoped to the function echo \"hello, $name\" } greet \"alice\" # \"return\" a value by printing it, then capture with $( ) get_ext() { echo \"${1##*.}\"; } ext=$(get_ext \"report.pdf\") # pdf # `return` sets the exit status (0\u2013255), used for true/false is_number() { [[ \"$1\" =~ ^-?[0-9]+$ ]]; } if is_number \"42\"; then echo \"yes\"; fi # all args, arg count show_args() { echo \"$# args: $*\"; for a in \"$@\"; do echo \" - $a\"; done; }"}, {"id": "arguments", "url": "arguments.html", "title": "Arguments & getopts", "text": "arguments & getopts short options with getopts verbose=0; output=\"\" while getopts \":vo:h\" opt; do # leading \":\" = handle errors yourself case \"$opt\" in # \"o:\" = -o takes a value v) verbose=1 ;; o) output=\"$optarg\" ;; h) usage; exit 0 ;; :) echo \"-$optarg needs a value\" >&2; exit 1 ;; \\?) echo \"unknown option -$optarg\" >&2; exit 1 ;; esac done shift $((optind - 1)) # \"$@\" now holds the remaining args long options (manual loop) while [[ $# -gt 0 ]]; do case \"$1\" in -v|--verbose) verbose=1; shift ;; -o|--output) output=\"$2\"; shift 2 ;; --output=*) output=\"${1#*=}\"; shift ;; --) shift; break ;; -*) echo \"unknown option $1\" >&2; exit 1 ;; *) args+=(\"$1\"); shift ;; esac done"}, {"id": "redirection", "url": "redirection.html", "title": "Redirection & pipes", "text": "redirection & pipes syntax effect cmd > file stdout to file (overwrite) cmd >> file stdout to file (append) cmd 2> file stderr to file cmd > file 2>&1 stdout and stderr to file (order matters) cmd &> file same as above (bash shorthand) cmd > /dev/null 2>&1 discard all output cmd < file file as stdin echo \"msg\" >&2 write to stderr (for errors and logs) cmd1 | cmd2 stdout of cmd1 \u2192 stdin of cmd2 cmd1 |& cmd2 stdout and stderr piped cmd | tee file show output and save it ( tee -a appends) command chaining syntax runs cmd2\u2026 cmd1 ; cmd2 always cmd1 && cmd2 only if cmd1 succeeded cmd1 || cmd2 only if cmd1 failed cmd & runs cmd in the background; wait waits for it ( cmd1; cmd2 ) in a subshell (a cd there doesn't affect the parent) { cmd1; cmd2; } grouped in the current shell"}, {"id": "heredocs", "url": "heredocs.html", "title": "Here-docs & substitution", "text": "here-docs & substitution # here-doc: multi-line input (variables expand) cat <<eof > config.ini user=$user home=$home eof # quoted delimiter: no expansion (good for writing scripts) cat <<'eof' echo \"$home is not expanded here\" eof # <<- strips leading tabs, so you can indent the body if true; then cat <<-eof indented with tabs eof fi # here-string grep -o '[0-9]*' <<< \"order 1234\" # command substitution now=\"$(date '+%y-%m-%d %h:%m')\" # process substitution: treat command output as a file diff <(sort a.txt) <(sort b.txt) while read -r line; do echo \"$line\"; done < <(find . -name '*.md')"}, {"id": "reading", "url": "reading.html", "title": "Reading input & files", "text": "reading input & files # prompt the user read -rp \"your name: \" name read -rsp \"password: \" pass; echo # -s = silent read -rt 5 -p \"quick! \" ans || echo \"timed out\" # read a file line by line (the correct way) while ifs= read -r line; do echo \"\u2192 $line\" done < file.txt # split fields (csv-ish) while ifs=, read -r name email role; do echo \"$name <$email> ($role)\" done < users.csv # handle filenames with spaces/newlines from find find . -type f -print0 | while ifs= read -r -d '' f; do echo \"$f\" done # whole file into a variable content=\"$(< file.txt)\" ifs= keeps leading and trailing whitespace. -r stops backslashes from being treated as escape characters. use both every time you read lines."}, {"id": "errors", "url": "errors.html", "title": "Exit codes & errors", "text": "exit codes & error handling code meaning 0 success 1 general error 2 misuse of shell builtin / bad usage 126 command found but not executable 127 command not found 128+n killed by signal n (130 = ctrl-c, 137 = kill -9) die() { echo \"error: $*\" >&2; exit 1; } [[ -r \"$config\" ]] || die \"cannot read $config\" cd \"$dir\" || die \"cd failed\" # check status explicitly if ! output=$(some_command 2>&1); then die \"some_command failed: $output\" fi # allow a command to fail under set -e rm -f maybe.txt || true # require dependencies for cmd in curl jq git; do command -v \"$cmd\" >/dev/null || die \"missing dependency: $cmd\" done # require root (( euid == 0 )) || die \"run as root (sudo)\""}, {"id": "traps", "url": "traps.html", "title": "Traps & cleanup", "text": "traps & cleanup tmp=\"$(mktemp -d)\" cleanup() { rm -rf \"$tmp\"; } trap cleanup exit # runs however the script exits trap 'echo \"interrupted\"; exit 130' int term # report the line where an error occurred trap 'echo \"error on line $lineno\" >&2' err # simple lock so only one copy of the script runs at once lock=\"/tmp/$(basename \"$0\").lock\" if ! mkdir \"$lock\" 2>/dev/null; then echo \"already running\" >&2; exit 1 fi trap 'rm -rf \"$lock\"' exit"}, {"id": "debugging", "url": "debugging.html", "title": "Debugging", "text": "debugging bash -n script.sh # syntax check only, no execution bash -x script.sh # print each command as it runs set -x \u2026 set +x # trace only one section # more informative trace prefix export ps4='+ ${bash_source}:${lineno}: ${funcname[0]:+${funcname[0]}(): }' # static analysis (strongly recommended) shellcheck script.sh # brew install shellcheck / apt install shellcheck"}, {"id": "best-practices", "url": "best-practices.html", "title": "Best practices", "text": "best practices start with #!/usr/bin/env bash and set -euo pipefail . quote every expansion: \"$var\" , \"$@\" , \"$(cmd)\" . use [[ ]] for tests and (( )) for arithmetic. declare function variables with local . send errors and logs to stderr ( >&2 ) so stdout stays clean for piping. never parse ls . use globs or find -print0 . use $(\u2026) , not backticks. use mktemp for temp files and clean up with trap \u2026 exit . write rm -- \"$file\" so a filename that starts with - isn't read as an option. guard dangerous paths: rm -rf \"${dir:?}/\"* refuses to run if dir is empty. give risky scripts a dry-run mode, and print a usage message for -h . run shellcheck on everything. once a script grows past about 200 lines or needs complex data structures, switch to python."}, {"id": "cmd-files", "url": "cmd-files.html", "title": "Files & directories", "text": "files & directories command purpose ls -lah list all files, long format, human-readable sizes cd - go back to the previous directory pwd print working directory mkdir -p a/b/c create nested directories cp -r src dest copy recursively ( -a preserves attributes) mv old new move or rename rm -rf dir delete recursively, no prompt (careful!) ln -s target link create a symlink touch file create file / update timestamp chmod 755 f / chmod +x f change permissions chown user:group f change owner stat file detailed file info realpath file absolute path rsync -avh src/ dest/ sync directories (add --delete to mirror) du -sh * size of each item here df -h free disk space find find . -name \"*.log\" # by name (-iname = case-insensitive) find . -type f -size +100m # files over 100 mb find . -type f -mtime -1 # modified in the last 24 h find . -type d -empty -delete # delete empty dirs find . -name \"*.tmp\" -exec rm {} + # run a command on matches find . -type f -name \"*.sh\" -print0 | xargs -0 chmod +x find . -path ./node_modules -prune -o -name \"*.js\" -print # exclude a dir"}, {"id": "cmd-text", "url": "cmd-text.html", "title": "Text processing", "text": "text processing command purpose cat / less print / page through a file head -n 20 / tail -n 20 first / last lines tail -f app.log follow a file as it grows wc -l count lines ( -w words, -c bytes) sort sort lines ( -n numeric, -r reverse, -u unique, -k2 by column 2) uniq -c count adjacent duplicates (sort first) cut -d, -f1,3 extract fields 1 and 3 from csv tr 'a-z' 'a-z' translate characters ( -d deletes) paste -sd, join lines with commas column -t align output into a table diff -u a b compare files xargs build commands from stdin ( -n1 , -p4 parallel) jq query and transform json grep grep \"error\" app.log # lines containing \"error\" grep -i \"error\" app.log # case-insensitive grep -v \"debug\" app.log # lines not matching grep -rn \"todo\" src/ # recursive, with line numbers grep -e \"warn|error\" app.log # extended regex (alternation) grep -o \"[0-9]\\+\\.[0-9]\\+\" f # print only the match grep -c \"error\" app.log # count matching lines grep -l \"foo\" *.txt # list files that match grep -a3 -b1 \"panic\" app.log # 3 lines after, 1 before sed sed 's/old/new/' file # replace first match per line sed 's/old/new/g' file # replace all sed -i 's/old/new/g' file # edit in place (gnu) sed -i '' 's/old/new/g' file # edit in place (macos/bsd) sed -n '10,20p' file # print lines 10\u201320 sed '/^#/d' file # delete comment lines sed '/^$/d' file # delete blank lines sed -e 's/([a-z]+)@/\\1 at /' f # capture groups awk awk '{print $1}' file # first column (whitespace-split) awk -f, '{print $2}' data.csv # custom separator awk '$3 > 100' file # filter rows awk '{sum += $2} end {print sum}' file # sum a column awk 'nr > 1' file # skip header line awk '{print nr\": \"$0}' file # number lines awk -f: '{print $1, $nf}' /etc/passwd # first and last field awk '{count[$1]++} end {for (k in count) print count[k], k}' access.log classic pipelines # top 10 most frequent words tr -cs '[:alpha:]' '\\n' < book.txt | tr 'a-z' 'a-z' | sort | uniq -c | sort -rn | head # most common lines in a log sort app.log | uniq -c | sort -rn | head # pretty-print and filter json curl -s https://api.github.com/repos/torvalds/linux | jq '{name, stars: .stargazers_count}'"}, {"id": "cmd-system", "url": "cmd-system.html", "title": "System & processes", "text": "system & processes command purpose ps aux all running processes ps aux | grep [n]ginx find a process (the [n] trick hides grep itself) pgrep -fl name find pids by name top / htop live process monitor kill pid ask a process to stop (sigterm) kill -9 pid force kill (sigkill) pkill -f pattern kill by name / pattern jobs / fg / bg manage shell jobs (ctrl-z suspends) nohup cmd & keep running after logout lsof -i :8080 what's using port 8080 uname -a kernel / os info uptime uptime and load average free -h memory usage (linux) whoami / id current user / groups env / printenv environment variables which cmd / type cmd where a command comes from time cmd measure how long a command takes watch -n 2 cmd re-run every 2 seconds crontab -e edit scheduled jobs systemctl status svc service status (systemd) journalctl -u svc -f follow a service's logs cron syntax # \u250c minute (0-59) # \u2502 \u250c hour (0-23) # \u2502 \u2502 \u250c day of month (1-31) # \u2502 \u2502 \u2502 \u250c month (1-12) # \u2502 \u2502 \u2502 \u2502 \u250c day of week (0-7, sun=0 or 7) # * * * * * command 0 2 * * * /path/backup.sh # daily at 02:00 */15 * * * * /path/healthcheck.sh # every 15 minutes 0 9 * * 1-5 /path/report.sh # weekdays at 09:00 @reboot /path/startup.sh # at boot"}, {"id": "cmd-network", "url": "cmd-network.html", "title": "Networking", "text": "networking curl -fssl https://example.com # fetch (fail on http errors, silent, follow redirects) curl -o file.zip https://example.com/f.zip curl -x post -h \"content-type: application/json\" -d '{\"a\":1}' https://api.example.com curl -i https://example.com # headers only curl -w '%{http_code}\\n' -o /dev/null -s https://example.com # status code only wget -q https://example.com/file ssh user@host # remote shell ssh user@host 'df -h' # run one remote command ssh -l 8080:localhost:80 user@host # local port forward scp file.txt user@host:/tmp/ # copy to remote rsync -avz ./site/ user@host:/var/www/ # efficient sync over ssh ssh-keygen -t ed25519 && ssh-copy-id user@host ping -c 4 host dig example.com +short # dns lookup nc -zv host 22 # is a port open? ss -tulpn # linux / lsof -itcp -stcp:listen # macos \u2014 listening ports"}, {"id": "cmd-archive", "url": "cmd-archive.html", "title": "Archives", "text": "archives command purpose tar -czf out.tar.gz dir/ create gzip tarball tar -xzf file.tar.gz extract (add -c dir for destination) tar -tzf file.tar.gz list contents tar -cjf out.tar.xz dir/ xz compression (smaller, slower) zip -r out.zip dir/ create zip unzip file.zip -d dest/ extract zip gzip f / gunzip f.gz compress / decompress a single file zcat f.gz / zgrep pat f.gz read / search without extracting to remember the tar flags: c reate, e x tract, lis t , z = gzip, f = file (always last, because the filename follows it)."}, {"id": "shortcuts", "url": "shortcuts.html", "title": "Shell shortcuts", "text": "shell shortcuts keys / syntax action ctrl-a / ctrl-e jump to start / end of line ctrl-w / ctrl-u / ctrl-k delete word / to start / to end ctrl-r search command history ctrl-l clear screen ctrl-c / ctrl-z / ctrl-d interrupt / suspend / exit (eof) !! repeat last command ( sudo !! ) !$ last argument of previous command !grep re-run last command starting with grep ^old^new re-run last command with a substitution alt-. insert last argument (press repeatedly to cycle) history | grep x search history alias ll='ls -lah' define a shortcut (put in ~/.bashrc )"}, {"id": "examples", "url": "examples.html", "title": "Example scripts", "text": "example scripts complete, tested scripts from the scripts/ folder. pick one to read the source, then copy it or download the raw file. download view on github quick start git clone https://github.com/choicespecs/bash-reference.git cd bash-reference/scripts ./backup.sh ~/documents ~/backups 7 # or grab a single script curl -fsslo https://choicespecs.github.io/bash-reference/scripts/retry.sh && chmod +x retry.sh"}];
